// Generated by `fe anim export` (fizlet-engine factory/anim-make.mjs): change it there, not here.
// The recipe matcher and the snippet maker, in one pure module (no imports, no Node, no DOM): the
// factory runs it (fe anim, fe anim --snippet) and the Fizlet site runs a copy of it in the browser
// (fizlet.com/make/, written there by `fe anim export`). One source: the recipe table is data
// (anim.mjs recipeTable(): the regexes as their source text, the token colours as hex), so the
// same prompt makes the same spec and the same snippet, byte for byte, wherever it runs.
//
//   matchPrompt(table, prompt)   prompt → { id, prompt, title, recipe, scene, bricks, params, matched }
//   variantOf(spec)              which prebuilt scene bundle a spec needs (scene + the fizlet/fx kind it names)
//   variants(table)              every variant (the site builds them all; the factory only the one it needs)
//   snippetEntry(variant, paths) the source esbuild bundles into a variant's template (one __FIZLET__ hole)
//   makeSnippet(...)             template + spec → the drop-in file, its gzip size in its own header
// By Chris Cooley. MIT (the copy in coded-dot-design/fizlet).

const re = (src) => new RegExp(src);
export const words = (s) => s.toLowerCase().match(/[a-z0-9]+/g) ?? [];
const hits = (src, text) => [...text.matchAll(new RegExp(src, "g"))].map((m) => m[0]);
const first = (text, table) => {
  let best = null;
  for (const [name, src] of table) {
    const m = re(src).exec(text);
    if (m && (!best || m.index < best.index)) best = { name, index: m.index, word: m[0] };
  }
  return best;
};

/** Prompt words no table matched (stop words aside), in order: what to build next. */
export const missesOf = (table, prompt, matched) => {
  const known = new Set(Object.values(matched).flat().flatMap(words)), stop = new Set(table.stop);
  return [...new Set(words(prompt).filter((w) => !stop.has(w) && !known.has(w)))];
};
export const slug = (table, prompt) => {
  const stop = new Set(table.stop);
  return words(prompt).filter((w) => !stop.has(w)).slice(0, 5).join("-").slice(0, 48).replace(/-+$/, "") || "anim";
};

/** A prompt → the spec's matched parts (no date: the factory adds it). Same prompt → same result. */
export function matchPrompt(table, prompt) {
  const p = String(prompt ?? "").trim();
  if (p.length < 3) throw new Error('fe anim: give a prompt, e.g. fe anim "pink sparks burst where you tap"');
  const text = p.toLowerCase(), T = table, recipes = Object.entries(T.recipes);
  // A verb picks the recipe ("confetti pops": burst); with no verb, the first noun does ("snow").
  const r = first(text, recipes.map(([k, v]) => [k, v.verbs])) ?? first(text, recipes.map(([k, v]) => [k, v.nouns]));
  const recipe = r?.name ?? T.defaultRecipe, R = T.recipes[recipe];
  const k = first(text, Object.entries(T.kinds).map(([n, v]) => [n, v.re]));
  const kindName = k?.name ?? R.kind;
  const colorHits = T.colors.filter(([src]) => re(src).test(text));
  // Comic words a point burst pops (POW, BAM, ZAP), in comic-book colours unless the prompt names its own.
  const comic = R.source === "point" && T.comic ? [...new Set(hits(T.comic, text))] : [];
  const colors = colorHits.length ? [...new Set(colorHits.flatMap(([, roles]) => roles))] : comic.length ? ["hurt", "attack", "sys", "flag"] : [...R.colors];
  if (colors.length === 1) colors.push(colors[0] === "flag" ? "sys" : "flag"); // one colour reads flat: add a highlight
  const amountHits = T.amount.filter(([src]) => re(src).test(text)), scaleHits = T.scale.filter(([src]) => re(src).test(text));
  const amount = amountHits.reduce((a, [, f]) => a * f, 1), scale = scaleHits.reduce((a, [, f]) => a * f, R.scale);
  const loop = re(T.loop).test(text);
  const page = (T.pageScenes ?? ["page"]).includes(R.scene);
  const sel = page ? first(text, T.select.map(([src, css]) => [css, src])) : null;
  const matched = {
    recipe: r ? [...hits(R.verbs, text), ...hits(R.nouns, text)] : [],
    kind: k ? hits(T.kinds[k.name].re, text) : [],
    colors: colorHits.flatMap(([src]) => hits(src, text)),
    amount: [...amountHits, ...scaleHits].flatMap(([src]) => hits(src, text)),
    loop: hits(T.loop, text),
    select: sel ? [sel.word] : [],
    tap: hits(T.tap, text),
  };
  if (comic.length) matched.words = comic;
  matched.miss = missesOf(T, p, matched);
  let params;
  if (page) {
    params = {
      effect: R.effect,
      select: sel?.name ?? R.select,
      colors: colors.slice(0, 8),
      count: Math.round(R.count * (R.effect === "pool" ? amount : 1)),
      seconds: R.seconds,
      glow: R.glow,
      loop: loop ? R.loop : 0,
      scale: Math.round(scale * 100) / 100,
    };
  } else {
    const kind = { name: kindName, builtin: kindName in T.fxBuiltins };
    if (!kind.builtin) kind.def = T.kinds[kindName].def;
    // An edge source aims across the stage from its edge; a point keeps the kind's own direction.
    if (T.edges[R.source]) Object.assign(kind, T.edges[R.source]);
    params = {
      source: R.source,
      kind,
      colors: colors.slice(0, 8),
      count: Math.round(R.count * amount),
      seconds: R.seconds,
      gravity: R.gravity,
      loop: loop ? (R.source === "point" ? R.loop : R.seconds) : 0,
      scale: Math.round(scale * 100) / 100,
      ...(comic.length && { words: comic.map((w) => w.toUpperCase()) }),
      ...(/\bhover/.test(text) && { hover: true }),
    };
  }
  return {
    id: slug(T, p),
    prompt: p,
    title: (p[0].toUpperCase() + p.slice(1)).replace(/[.!]+$/, "").slice(0, 80),
    recipe,
    scene: R.scene,
    bricks: [...T.bricks[R.scene]],
    params,
    matched,
  };
}

// ---------- the snippet ----------

/** The prebuilt scene bundle a spec needs: the scene, plus the fizlet/fx built-in kind it imports (if any) or its decor effect. */
export const variantOf = (table, spec) =>
  spec.scene === "spray" && spec.params.kind.builtin ? `spray-${table.fxBuiltins[spec.params.kind.name]}` : spec.scene === "decor" ? `decor-${spec.params.effect}` : spec.scene;
/** Every variant: what the site prebuilds (a variant is one template; a snippet fills its one hole). */
export const variants = (table) => [...new Set(Object.values(table.recipes).map((r) => r.scene))].flatMap((s) =>
  s === "spray" ? ["spray", ...Object.values(table.fxBuiltins).map((b) => `spray-${b}`)]
  : s === "decor" ? Object.values(table.recipes).filter((r) => r.scene === "decor").map((r) => `decor-${r.effect}`) : [s]);
export const HOLE = "__FIZLET__";
/** The esbuild options every template is built with, here and on the site (one build, one size). */
export const TEMPLATE_BUILD = { bundle: true, minify: true, format: "esm", target: "es2022", legalComments: "none", logLevel: "warning", write: false };

/**
 * The entry esbuild bundles into a variant's template. `paths`: where fizlet/slot, fizlet/fx and the
 * scenes resolve (bare for the factory, relative for the site; the bundle is the same). It mounts
 * every `[data-fizlet="<id>"]` once through fizlet/slot (near the viewport, never under reduced
 * motion, Recall through the slot's ledger) and leaves the handle on the element: el.fizlet.slot
 * (destroy() gives the page back) and el.fizlet.scene (its engine).
 */
export function snippetEntry(variant, { slot, fx, scenes }) {
  const [scene, part] = variant.split("-"), decor = scene === "decor", builtin = decor ? undefined : part;
  const kind = scene === "spray" ? (builtin ? "{ ...K, ...P.params.kind }" : "P.params.kind") : null;
  // A decor variant imports only its own effect.
  return `import { slot } from ${JSON.stringify(slot)};
import { scene${decor ? `, ${part} as E` : ""} } from ${JSON.stringify(`${scenes}/${scene}`)};
${builtin ? `import { ${builtin} as K } from ${JSON.stringify(fx)};\n` : ""}const P = ${HOLE};
const make = scene(${decor ? "E, " : ""}${kind ? `{ ...P.params, kind: ${kind} }` : "P.params"});
for (const el of document.querySelectorAll("[data-fizlet]"))
  if (el.dataset.fizlet === P.id && !el.fizlet) {
    const h = (el.fizlet = { scene: null });
    h.slot = slot(el, () => (stage, s, first) => (h.scene = make(stage, s, first)));
  }
`;
}

/** What fills the hole: the id and the scene's data, colours as hex (a built-in kind: only its overrides). */
export function snippetData(table, spec) {
  const { kind, ...p } = spec.params;
  const params = { ...p, colors: p.colors.map((role) => table.tokens[role]) };
  if (kind) {
    const over = Object.fromEntries(["angle", "spread"].filter((k) => kind[k] !== undefined).map((k) => [k, kind[k]]));
    params.kind = kind.builtin ? over : { ...kind.def, ...over };
  }
  return { id: spec.id, params };
}

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const fmt = (n) => n.toLocaleString("en-US");
/** A page scene reads the page in its mount: this sample (headings, a paragraph, a link, keys) shows it; swap in your own. */
export const SAMPLE_PAGE = `\n  <h2>Hello, page.</h2>\n  <p>Real elements under a Fizlet scene: put your own here.</p>\n  <h3>Every heading is real</h3>\n  <p><a href="https://fizlet.com/">A link</a> <button type="button">Hover me</button> <button type="button">Or me</button></p>\n`;

/** The snippet's text for a given size line (the size is of this very text: makeSnippet finds it). */
export function renderSnippet(table, spec, template, { version, size, pad = 0 }) {
  const holes = template.split(HOLE).length - 1;
  if (holes !== 1) throw new Error(`snippet template: expected one ${HOLE} hole, found ${holes}`);
  const data = JSON.stringify(snippetData(table, spec)).replace(/</g, "\\u003c");
  const code = template.replace(HOLE, () => `(${data})`).trimEnd();
  const page = spec.scene !== "spray";
  const prompt = esc(spec.prompt).replace(/-{2,}/g, "-");
  const head = `<!-- Fizlet snippet: "${prompt}"${" ".repeat(pad)}
     ${size === null ? "?" : fmt(size)} B gzip, this whole file (measured when it was made). Fizlet ${version}, recipe ${spec.recipe}: ${spec.bricks.join(" + ")}.
     By Chris Cooley (https://coded.design). MIT licence: https://github.com/coded-dot-design/fizlet
     Paste it where it should play. It starts near the viewport, never runs under reduced motion,
     sleeps once still, and el.fizlet.slot.destroy() gives the page back exactly. -->`;
  const mount = page
    ? `<div data-fizlet="${spec.id}" style="position:relative">${SAMPLE_PAGE}</div>`
    : `<div data-fizlet="${spec.id}" role="img" aria-label="${esc(spec.title)}" style="position:relative;aspect-ratio:16/9;cursor:pointer"></div>`;
  return `${head}\n${mount}\n<script type="module">\n/*! Fizlet snippet · by Chris Cooley · MIT · https://github.com/coded-dot-design/fizlet */\n${code}\n</script>\n`;
}

/**
 * The drop-in file: the template filled with the spec, with its own gzip size in its header.
 * `gzipSize(text)` measures (Node zlib in the factory and the site build, CompressionStream in the
 * browser: the same deflate, the same bytes in Chromium). The size line is part of the file, so it
 * is found by fixed point: render, measure, render with that number, until the number holds. When
 * two numbers take turns, the larger one is kept and the header line is padded with spaces until
 * the file measures exactly that (deterministic: the same steps everywhere).
 */
export async function makeSnippet(table, spec, template, { version, gzipSize }) {
  const seen = new Set();
  let size = null;
  for (let i = 0; i < 8; i++) {
    const text = renderSnippet(table, spec, template, { version, size });
    const n = await gzipSize(text);
    if (n === size) return { text, size };
    if (seen.has(n)) break;
    seen.add(n);
    size = n;
  }
  size = Math.max(...seen);
  for (let pad = 1; pad <= 512; pad++) {
    const text = renderSnippet(table, spec, template, { version, size, pad });
    const n = await gzipSize(text);
    if (n === size) return { text, size };
    if (n > size) size = n;
  }
  throw new Error("snippet: its gzip size did not settle");
}
